def patch_one(op, do_apply):
    path = ROOT / op["file"]
    if not path.exists():
        raise SystemExit(f"FAIL: missing {op['file']}")

    text = path.read_text(encoding="utf-8")
    old = op["old"]
    new = op["new"]
    old_count = text.count(old)
    new_count = text.count(new)

    if new_count == 1:
        print(f"SKIP: already applied: {op['name']}")
        return

    if old_count == 1 and new_count == 0:
        print(f"READY: {op['name']}")
        if do_apply:
            path.write_text(
                text.replace(old, new, 1),
                encoding="utf-8",
                newline="\n",
            )
            print(f"APPLIED: {op['name']}")
        return

    raise SystemExit(
        f"FAIL: anchor mismatch for {op['name']}: "
        f"old={old_count}, new={new_count}"
    )

def ensure_new_file(rel, content, do_apply):
    path = ROOT / rel
    if path.exists():
        current = path.read_text(encoding="utf-8")
        if current == content:
            print(f"SKIP: already present: {rel}")
            return
        raise SystemExit(f"FAIL: unexpected existing file differs: {rel}")

    print(f"READY: create {rel}")
    if do_apply:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        print(f"CREATED: {rel}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    do_apply = not args.check

    for op in OPS:
        patch_one(op, do_apply)

    for rel, content in NEW_FILES.items():
        ensure_new_file(rel, content, do_apply)

    print(
        "PASS: corrective navigation wave anchors ready/already applied"
        if args.check
        else "PASS: corrective navigation wave applied"
    )

if __name__ == "__main__":
    main()
